// rows reads a JSONL corpus generated by Python (testdata here, or the shared testdata/pycompat).
func rows(t *testing.T, path string, each func(row map[string]json.RawMessage)) {
	t.Helper()
	f, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	n := 0
	for scanner.Scan() {
		n++
		var row map[string]json.RawMessage
		// Python writes NaN for a float nan, which is not JSON.
		line := strings.ReplaceAll(scanner.Text(), ": NaN", `: "NaN"`)
		if err := json.Unmarshal([]byte(line), &row); err != nil {
			t.Fatalf("%s:%d: %v", path, n, err)
		}
		each(row)
	}
	if n == 0 {
		t.Fatalf("%s is empty", path)
	}
}

func shared(name string) string { return filepath.Join("..", "..", "..", "testdata", "pycompat", name) }
func local(name string) string  { return filepath.Join("testdata", name) }

func value(t *testing.T, raw json.RawMessage) py.Value {
	t.Helper()
	var v py.Value
	if err := v.UnmarshalJSON(raw); err != nil {
		t.Fatal(err)
	}
	return v
}

func isPyError(raw json.RawMessage) bool { return strings.Contains(string(raw), `"error"`) }

func TestTimeleftMatchesPython(t *testing.T) {
	for _, path := range []string{shared("arr_timeleft.jsonl"), local("arr_timeleft.jsonl")} {
		rows(t, path, func(row map[string]json.RawMessage) {
			in := value(t, row["s"])
			got, ok := TimeleftSeconds(in)
			want := value(t, row["seconds"])
			switch {
			case isPyError(row["seconds"]):
				// Python's OverflowError killed the job; here the item simply has no timeleft.
				if ok {
					t.Errorf("timeleft(%s) = %d, Python raised", in.Repr(), got)
				}
			case want.IsNone():
				if ok {
					t.Errorf("timeleft(%s) = %d, want None", in.Repr(), got)
				}
			default:
				if w, _ := want.AsInt(); !ok || got != w {
					t.Errorf("timeleft(%s) = %d, %v; want %d", in.Repr(), got, ok, w)
				}
			}
		})
	}
}

func TestDurationMatchesPython(t *testing.T) {
	for _, path := range []string{shared("arr_duration.jsonl"), local("arr_duration.jsonl")} {
		rows(t, path, func(row map[string]json.RawMessage) {
			in := value(t, row["s"])
			got := DurationSeconds(in)
			if string(row["seconds"]) == `"NaN"` {
				if !math.IsNaN(got) {
					t.Errorf("duration(%s) = %v, want nan", in.Repr(), got)
				}
				return
			}
			want := value(t, row["seconds"])
			if py.FloatRepr(got) != want.String() {
				t.Errorf("duration(%s) = %s, want %s", in.Repr(), py.FloatRepr(got), want)
			}
		})
	}
}

func TestParseArrDateMatchesPython(t *testing.T) {
	for _, path := range []string{shared("arr_dates.jsonl"), local("arr_dates.jsonl")} {
		rows(t, path, func(row map[string]json.RawMessage) {
			in := value(t, row["s"])
			got, ok := ParseArrDate(in)
			want := value(t, row["iso"])
			if want.IsNone() {
				if ok {
					t.Errorf("parse(%s) = %s, want None", in.Repr(), py.IsoFormat(got))
				}
				return
			}
			if !ok || py.IsoFormat(got) != want.String() {
				t.Errorf("parse(%s) = %s, %v; want %s", in.Repr(), py.IsoFormat(got), ok, want)
			}
		})
	}
}

func TestDateFromISOFormatMatchesPython(t *testing.T) {
	rows(t, local("calendar_dates.jsonl"), func(row map[string]json.RawMessage) {
		in := value(t, row["s"])
		got, ok := DateFromISOFormat(py.Truncate(in.String(), 10))
		if isPyError(row["date"]) {
			if ok {
				t.Errorf("date(%s) = %s, Python raised", in.Repr(), got.Format("2006-01-02"))
			}
			return
		}
		if want := value(t, row["date"]).String(); !ok || got.Format("2006-01-02") != want {
			t.Errorf("date(%s) = %s, %v; want %s", in.Repr(), got.Format("2006-01-02"), ok, want)
		}
	})
}

func TestQualityNameMatchesPython(t *testing.T) {
	rows(t, local("quality_name.jsonl"), func(row map[string]json.RawMessage) {
		var q py.Obj[quality]
		_ = q.UnmarshalJSON(row["v"])
		got := QualityName(q)
		if want := value(t, row["name"]); !got.Equal(want) {
			t.Errorf("quality_name(%s) = %s, want %s", row["v"], got.Repr(), want.Repr())
		}
	})
}

func TestToIntMatchesPython(t *testing.T) {
	rows(t, shared("arr_to_int.jsonl"), func(row map[string]json.RawMessage) {
		in := value(t, row["v"])
		got := py.ToInt(in, 0)
		if isPyError(row["int"]) {
			if got != 0 {
				t.Errorf("to_int(%s) = %d, want the default", in.Repr(), got)
			}
			return
		}
		if want := value(t, row["int"]); fmt.Sprint(got) != want.String() && !want.IsBig() {
			t.Errorf("to_int(%s) = %d, want %s", in.Repr(), got, want)
		}
	})
}

func TestVolumeContains(t *testing.T) {
	cases := []struct {
		volume, path string
		want         bool
	}{
		{"/", "/anything", true},
		{"/data", "/data/tv", true},
		{"/data", "/data", true},
		{"/data/", "/data/tv/", true},
		{"/data", "/data2/tv", false},
		{"/data2", "/data/tv", false},
		{`C:\`, `C:\TV`, true},
		{`D:\Media`, `D:\Media\TV`, true},
		{`D:\Media`, `D:\Media2`, false},
		{"/mnt/tv/", "/mnt/tv/shows/", true},
	}
	for _, c := range cases {
		if got := VolumeContains(c.volume, c.path); got != c.want {
			t.Errorf("VolumeContains(%q, %q) = %v", c.volume, c.path, got)
		}
	}
}

func TestNested(t *testing.T) {
	cases := map[string][3]bool{ // object, truthy, invalid
		`{"title": "x"}`: {true, true, false},
		`{}`:             {true, false, false},
		` { } `:          {true, false, false},
		`null`:           {false, false, false},
		`""`:             {false, false, false},
		`"text"`:         {false, true, true},
		`[1]`:            {false, true, true},
		`0`:              {false, false, false},
	}
	for raw, want := range cases {
		var n Nested[SeriesRef]
		if err := n.UnmarshalJSON([]byte(raw)); err != nil {
			t.Fatal(err)
		}
		if got := [3]bool{n.IsObject(), n.Truthy(), n.Invalid()}; got != want {
			t.Errorf("%s: got %v want %v", raw, got, want)
		}
	}
}

func TestSnakeCase(t *testing.T) {
	for in, want := range map[string]string{"importBlocked": "import_blocked", "failedPending": "failed_pending",
		"downloading": "downloading"} {
		if got := snakeCase(in); got != want {
			t.Errorf("snakeCase(%s) = %s", in, got)
		}
	}
}

func TestResolutionName(t *testing.T) {
	for raw, want := range map[string]string{`2160`: "2160p", `"1080"`: "1080p", `0`: "Unknown", `-1`: "Unknown",
		`null`: "Unknown", `720.9`: "720p"} {
		if got := ResolutionName(value(t, json.RawMessage(raw))); got != want {
			t.Errorf("ResolutionName(%s) = %s", raw, got)
		}
	}
}

func newBase(t *testing.T, handler http.HandlerFunc, deps collector.Deps) (*Base, *testutil.Capture) {
	t.Helper()
	srv := httptest.NewServer(handler)
	t.Cleanup(srv.Close)
	capture := &testutil.Capture{}
	deps.Writer = capture
	deps = deps.WithDefaults()
	return &Base{Measurement: "Sonarr", Prefix: "/api/v3", ServerID: 1, Deps: deps, Log: deps.Log,
		Client: NewClient(srv.URL, "key", false, nil, deps)}, capture
}

func TestFetchQueuePagesStopsWhenThePageDoesNotAdvance(t *testing.T) {
	var calls atomic.Int32
	b, _ := newBase(t, func(w http.ResponseWriter, r *http.Request) {
		calls.Add(1)
		_, _ = w.Write([]byte(`{"page": 1, "pageSize": 1, "totalRecords": 50, "records": [{"id": 1}]}`))
	}, collector.Deps{})
	records, ok := b.FetchQueuePages(context.Background(), func(page int) httpx.Params { return nil })
	if !ok || len(records) != 2 || calls.Load() != 2 {
		t.Errorf("ok=%v records=%d calls=%d", ok, len(records), calls.Load())
	}
}

func TestFetchQueuePagesCapsRunawayPaging(t *testing.T) {
	var calls atomic.Int32
	b, _ := newBase(t, func(w http.ResponseWriter, r *http.Request) {
		n := calls.Add(1)
		fmt.Fprintf(w, `{"page": %d, "pageSize": 1, "totalRecords": 1000000, "records": [{"id": %d}]}`, n, n)
	}, collector.Deps{})
	records, ok := b.FetchQueuePages(context.Background(), func(page int) httpx.Params {
		return httpx.P("page", fmt.Sprint(page))
	})
	if !ok || len(records) != maxQueuePages+1 {
		t.Errorf("ok=%v records=%d", ok, len(records))
	}
}

func TestHistoryEventsCappedToRetention(t *testing.T) {
	var date atomic.Value
	now := time.Date(2026, 11, 18, 16, 30, 0, 0, time.UTC)
	b, capture := newBase(t, func(w http.ResponseWriter, r *http.Request) {
		date.Store(r.URL.Query().Get("date"))
		_, _ = w.Write([]byte(`[{"id": 1, "eventType": "grabbed", "date": "2026-11-18T10:00:00Z"}]`))
	}, collector.Deps{
		Now:       func() time.Time { return now },
		Retention: func() time.Duration { return 30 * 24 * time.Hour },
	})
	if err := b.HistoryEvents(context.Background(), 364); err != nil {
		t.Fatal(err)
	}
	if got := date.Load(); got != "2026-10-19T16:30:00Z" {
		t.Errorf("since = %v, want 30 days back", got)
	}
	if !strings.Contains(capture.Lines(), "event_type=grabbed") || !strings.Contains(capture.Lines(), "protocol") &&
		!strings.Contains(capture.Lines(), "TORRENT") {
		t.Errorf("lines = %q", capture.Lines())
	}
	b.Deps.Retention = func() time.Duration { return 0 }
	if err := b.HistoryEvents(context.Background(), 7); err != nil {
		t.Fatal(err)
	}
	if got := date.Load(); got != "2026-11-11T16:30:00Z" {
		t.Errorf("since = %v, want 7 days back with infinite retention", got)
	}
}

func TestWriteErrorsArePropagated(t *testing.T) {
	b, _ := newBase(t, func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte(`[]`))
	}, collector.Deps{})
	b.Deps.Writer = failingWriter{}
	if err := b.Health(context.Background()); err == nil {
		t.Error("expected the write error")
	}
}

type failingWriter struct{}

func (failingWriter) Write(context.Context, []influx.Point) error { return fmt.Errorf("influx down") }

func TestFloorMod(t *testing.T) {
	if floorMod(-5, 1_000_000) != 999995 || floorMod(1234567, 1_000_000) != 234567 {
		t.Error("floorMod")
	}
}

func TestSecondsBetween(t *testing.T) {
	later := time.Date(2026, 1, 1, 0, 0, 1, 500_000_000, time.UTC)
	earlier := time.Date(2026, 1, 1, 0, 0, 2, 0, time.UTC)
	if got := secondsBetween(later, earlier); got != 0 {
		t.Errorf("-0.5s truncates to 0, got %d", got)
	}
	far, epoch71 := time.Date(9999, 1, 1, 0, 0, 0, 0, time.UTC), time.Date(1971, 1, 1, 0, 0, 0, 0, time.UTC)
	if got := secondsBetween(far, epoch71); got != far.Unix()-epoch71.Unix() {
		t.Errorf("long range = %d", got)
	}
}

func FuzzTimeleftSeconds(f *testing.F) {
	for _, s := range []string{"00:00:00", "1.02:03:04", "-1:00:00", "1_0:00:00", "00:00:1e2", "٣:00:00", ":"} {
		f.Add(s)
	}
	f.Fuzz(func(t *testing.T, s string) {
		if n, ok := TimeleftSeconds(py.String(s)); ok && strings.Count(s, ":") < 2 {
			t.Fatalf("%q parsed to %d without three parts", s, n)
		}
	})
}

func FuzzDurationSeconds(f *testing.F) {
	for _, s := range []string{"00:00:01.5000000", "1.02:03:04.5", "10:00", "x", "-00:00:01"} {
		f.Add(s)
	}
	f.Fuzz(func(t *testing.T, s string) {
		got := DurationSeconds(py.String(s))
		if got != 0 && strings.Count(s, ":") != 2 {
			t.Fatalf("%q gave %v without exactly two colons", s, got)
		}
	})
}

func FuzzParseArrDate(f *testing.F) {
	for _, s := range []string{"2026-11-18T16:30:00.1234567Z", "2026-W47-3T10:00:00Z", "20261118T163000Z", "Z.0"} {
		f.Add(s)
	}
	f.Fuzz(func(t *testing.T, s string) {
		if d, ok := ParseArrDate(py.String(s)); ok && (d.Year() < 1971 || d.Location() != time.UTC) {
			t.Fatalf("%q parsed to %v", s, d)
		}
	})
}
